arguments.sql_query:
SELECT COUNT(DISTINCT person_id) AS bipolar_source_f31_n
FROM omop.condition_occurrence
WHERE condition_source_value LIKE 'F31%';

WITH bipolar AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F31%'
), alcohol AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F10%'
)
SELECT COUNT(*) AS bipolar_n,
       (SELECT COUNT(*) FROM bipolar b JOIN alcohol a ON b.person_id=a.person_id) AS bipolar_with_alcohol_n
FROM bipolar;

WITH bipolar AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F31%'
), cannabis AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F12%'
)
SELECT COUNT(*) AS bipolar_n,
       (SELECT COUNT(*) FROM bipolar b JOIN cannabis s ON b.person_id=s.person_id) AS bipolar_with_cannabis_n
FROM bipolar;

WITH bipolar AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F31%'
), opioid AS (
  SELECT DISTINCT person_id FROM omop.condition_occurrence WHERE condition_source_value LIKE 'F11%'
)
SELECT COUNT(*) AS bipolar_n,
       (SELECT COUNT(*) FROM bipolar b JOIN opioid s ON b.person_id=s.person_id) AS bipolar_with_opioid_n
FROM bipolar;
